"""Privacy pages, consent-controlled analytics and click-to-load newsletters."""
import re
from pathlib import Path
from build_german import alternates, switch, de_nav
ROOT=Path(__file__).parent
OUT=ROOT/'public'

def newsletter(de):
    title='Neue Gedanken ins Postfach?' if de else 'Fresh thoughts in your inbox?'
    note=('Das Anmeldeformular wird von Sender bereitgestellt. Beim Öffnen wird eine Verbindung zu Sender hergestellt; dabei werden technische Verbindungsdaten wie Deine IP-Adresse übertragen.' if de else 'The signup form is provided by Sender. Opening it connects your browser to Sender and shares technical connection data, including your IP address.')
    button='Newsletter-Formular öffnen' if de else 'Open newsletter signup'
    fallback='Alternativ: Anmeldung direkt bei Sender öffnen ↗' if de else 'Alternatively: open signup directly on Sender ↗'
    return f'<section class="subscription" id="subscribe" aria-labelledby="subscribe-heading"><div class="subscription-copy"><h2 id="subscribe-heading">{title}</h2></div><div class="subscription-form"><p class="subscription-note">{note}</p><button class="newsletter-open" type="button" data-newsletter-open>{button}</button><p><a href="https://stats.sender.net/forms/epYyZ1/view" target="_blank" rel="noopener noreferrer">{fallback}</a></p></div></section>'

EN='''<h1>Privacy</h1><p>Last updated: 1 November 2026</p>
<h2>Who is responsible?</h2><p>Kay Lummitsch, Zürich, Switzerland. For privacy questions, access or deletion requests, contact <a href="mailto:kay@kaylummitsch.com">kay@kaylummitsch.com</a>.</p>
<h2>Website hosting and enquiries</h2><p>Cloudflare hosts and delivers this website. Visiting it sends technical connection data, including your IP address, requested address and browser information, to Cloudflare. This is used to deliver and protect the website. Technical logs and request statistics are separate from the optional visitor analytics below.</p><p>If you submit an Interview Rides enquiry, we process the information you enter, including your name, email address, riding preference, topic and region, to respond and plan the conversation. Enquiries are stored in Cloudflare D1 and an email notification is sent to Kay’s Gmail inbox. Cloudflare and Google therefore process the relevant data. The form has no public list of enquiries. Please do not include sensitive personal information.</p>
<h2>November conversations</h2><p>For a November meeting request, we process your name, email, topic, preferred date/time and format to arrange a free, no-obligation conversation. These requests are stored with Cloudflare and emailed to Kay, using a separate November category. They do not subscribe you to a newsletter. Conversations are confidential: no recording or automatic transcription. Please send only a short topic, not confidential details or other people’s personal data. A request does not reserve a time; Kay confirms personally. Google Meet, telephone or another platform by arrangement; the chosen provider processes connection data during the call.</p><h2>Optional visitor analytics</h2><p>Only if you select “Allow analytics”, we load Cloudflare Web Analytics. It measures page views, referral sources, browser and device categories, approximate country and loading times. Cloudflare states that this service uses no analytics cookies or persistent visitor profiles and discards the source IP at its nearest data centre. We use the results to understand which content is useful and improve the website.</p><p>You can refuse without losing access to the website. Use “Privacy & settings” to withdraw consent; the page reloads to stop the measurement script. Withdrawal does not delete statistics already collected. Browser blockers and non-consenting visits are not included in these measurements.</p>
<h2>Newsletter</h2><p>We load Sender’s embedded signup form only when you select “Open newsletter signup”. This connects your browser to Sender and transmits technical connection data such as your IP address. Sender’s form software can use cookies or browser storage, for example to recognise a subscriber. You can instead follow the separate link to Sender’s signup page.</p><p>If you subscribe, Sender processes your email address, subscription confirmation and delivery information to send the newsletter. You confirm your subscription by email and can unsubscribe using the link in each newsletter. Depending on the newsletter’s settings, opening or clicking a message may also be measured. The website analytics choice does not control tracking inside emails.</p>
<h2>What is saved in your browser?</h2><p>We save your privacy choice locally for up to 180 days (kay-privacy-v1). If you choose a language, we save that preference (kay-language). These settings help us respect your choices. They are not advertising identifiers. Clearing your browser storage removes them. If storage is unavailable, your choice may not survive a page change.</p>
<h2>Providers, retention and your rights</h2><p>Cloudflare, Sender and Google may process data outside Switzerland, including in the United States or other countries. Their own privacy information describes their processing and safeguards. We keep enquiry and correspondence data for as long as needed to respond, organise agreed activities and meet applicable retention obligations. Newsletter subscription data is managed through Sender; contact us if you want us to review or delete your data.</p><p>You can ask about your data, request correction or deletion, withdraw consent and contact the competent data protection authority, including Switzerland’s FDPIC. Requests and applicable rights depend on the processing and relevant law.</p><ul><li><a href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy information</a></li><li><a href="https://www.sender.net/privacy-policy/">Sender privacy information</a></li><li><a href="https://policies.google.com/privacy">Google privacy information</a></li><li><a href="https://www.edoeb.admin.ch/en">Swiss FDPIC</a></li></ul><p>External links, such as LinkedIn, open the respective provider’s website. Their privacy rules apply there.</p>'''
DE='''<h1>Datenschutz</h1><p>Stand: 1. November 2026</p>
<h2>Wer ist verantwortlich?</h2><p>Kay Lummitsch, Zürich, Schweiz. Für Datenschutzfragen, Auskunfts- oder Löschanfragen: <a href="mailto:kay@kaylummitsch.com">kay@kaylummitsch.com</a>.</p>
<h2>Website-Betrieb und Anfragen</h2><p>Cloudflare betreibt diese Website und liefert ihre Inhalte aus. Beim Besuch erhält Cloudflare technische Verbindungsdaten, darunter Deine IP-Adresse, die angefragte Adresse und Browserinformationen. Diese dienen der Auslieferung und dem Schutz der Website. Technische Protokolle und Anfragestatistiken sind von der freiwilligen Besuchsstatistik unten zu unterscheiden.</p><p>Wenn Du eine Interview-Rides-Anfrage absendest, verarbeiten wir Deine Angaben, darunter Name, E-Mail-Adresse, Fahrwunsch, Thema und Region, um zu antworten und das Gespräch zu planen. Anfragen werden in Cloudflare D1 gespeichert; Kay erhält eine Benachrichtigung in seinem Gmail-Postfach. Cloudflare und Google verarbeiten deshalb die entsprechenden Daten. Es gibt keine öffentliche Liste der Anfragen. Bitte gib keine besonders schützenswerten persönlichen Informationen ein.</p>
<h2>November-Gespräche</h2><p>Für eine November-Terminanfrage verarbeiten wir Name, E-Mail-Adresse, Themenstichwort, Wunschdatum/-zeit und Gesprächsformat, um ein kostenloses, unverbindliches Gespräch zu vereinbaren. Die Anfragen werden bei Cloudflare gespeichert und Kay per E-Mail zugestellt, mit einer eigenen November-Kategorie. Es entsteht keine Newsletter-Anmeldung. Das Gespräch ist vertraulich: keine Aufzeichnung oder automatische Transkription. Bitte sende nur ein Stichwort, keine vertraulichen Details oder persönlichen Daten anderer Menschen. Eine Anfrage reserviert keinen Termin; Kay bestätigt persönlich. Google Meet, Telefon oder eine andere Plattform nach Absprache; beim Gespräch verarbeitet der gewählte Anbieter Verbindungsdaten.</p><h2>Freiwillige Besuchsstatistik</h2><p>Nur wenn Du „Statistik erlauben“ auswählst, laden wir Cloudflare Web Analytics. Erfasst werden Seitenaufrufe, Herkunftsverweise, Browser- und Gerätekategorien, das ungefähre Land und Ladezeiten. Laut Cloudflare verwendet dieser Dienst keine Analyse-Cookies oder dauerhaften Besucherprofile und verwirft die Quell-IP-Adresse am nächstgelegenen Rechenzentrum. Wir nutzen die Ergebnisse, um hilfreiche Inhalte zu erkennen und die Website zu verbessern.</p><p>Du kannst ablehnen und die Website trotzdem vollständig nutzen. Unter „Datenschutz & Einstellungen“ kannst Du Deine Zustimmung widerrufen; dabei wird die Seite neu geladen, damit der Messcode nicht weiterläuft. Bereits erfasste Statistiken werden dadurch nicht gelöscht. Browserblocker und Besuche ohne Zustimmung fehlen in dieser Messung.</p>
<h2>Newsletter</h2><p>Das eingebundene Sender-Anmeldeformular laden wir erst, wenn Du „Newsletter-Formular öffnen“ auswählst. Dadurch verbindet sich Dein Browser mit Sender und überträgt technische Verbindungsdaten wie Deine IP-Adresse. Senders Formularsoftware kann Cookies oder Browserspeicher verwenden, etwa um Abonnenten wiederzuerkennen. Alternativ kannst Du dem separaten Link zur Anmeldeseite bei Sender folgen.</p><p>Bei einer Anmeldung verarbeitet Sender Deine E-Mail-Adresse, die Anmeldebestätigung und Zustellinformationen für den Newsletterversand. Du bestätigst Deine Anmeldung per E-Mail und kannst Dich über den Link in jedem Newsletter abmelden. Je nach Newsletter-Einstellung können auch Öffnungen und Klicks gemessen werden. Die Statistikauswahl auf dieser Website steuert keine Messung innerhalb von E-Mails.</p>
<h2>Was wird in Deinem Browser gespeichert?</h2><p>Deine Datenschutzauswahl speichern wir bis zu 180 Tage lokal (kay-privacy-v1). Wenn Du eine Sprache auswählst, speichern wir diese Präferenz (kay-language). Damit respektieren wir Deine Auswahl. Diese Einstellungen sind keine Werbekennungen. Wenn Du Deinen Browserspeicher löschst, werden sie entfernt. Ist die Speicherung nicht verfügbar, kann Deine Auswahl beim Seitenwechsel verloren gehen.</p>
<h2>Dienstleister, Aufbewahrung und Deine Rechte</h2><p>Cloudflare, Sender und Google können Daten ausserhalb der Schweiz verarbeiten, darunter in den USA oder anderen Ländern. Ihre eigenen Datenschutzinformationen erläutern Verarbeitung und Schutzmassnahmen. Anfragen und Korrespondenz bewahren wir so lange auf, wie es für die Antwort, vereinbarte Aktivitäten und geltende Aufbewahrungspflichten nötig ist. Newsletter-Anmeldedaten werden über Sender verwaltet; kontaktiere uns, wenn wir Deine Daten prüfen oder löschen sollen.</p><p>Du kannst Auskunft, Berichtigung oder Löschung anfragen, eine Zustimmung widerrufen und Dich an die zuständige Datenschutzbehörde wenden, darunter den Schweizer EDÖB. Die anwendbaren Rechte richten sich nach der Verarbeitung und dem geltenden Recht.</p><ul><li><a href="https://www.cloudflare.com/privacypolicy/">Datenschutz bei Cloudflare</a></li><li><a href="https://www.sender.net/privacy-policy/">Datenschutz bei Sender</a></li><li><a href="https://policies.google.com/privacy">Datenschutz bei Google</a></li><li><a href="https://www.edoeb.admin.ch/de">Schweizer EDÖB</a></li></ul><p>Externe Links, etwa zu LinkedIn, öffnen die Website des jeweiligen Anbieters. Dort gelten dessen Datenschutzregeln.</p>'''

def build():
    template=(OUT/'writing/turning-sixty/index.html').read_text()
    for de,route,body in [(False,'/privacy/',EN),(True,'/de/datenschutz/',DE)]:
        lang='de' if de else 'en'; title='Datenschutz' if de else 'Privacy'
        source=re.sub(r'<main\b.*?</main>',lambda m:'<main id="main" class="reading privacy-copy">'+body+'</main>',template,count=1,flags=re.S)
        source=re.sub(r'<title>.*?</title>',f'<title>{title} | Kay Lummitsch</title>',source,count=1)
        source=re.sub(r'<meta (?:name="(?:description|twitter:[^"]+)"|property="(?:og:[^"]+|article:[^"]+)")[^>]*>','',source)
        source=re.sub(r'<link rel="(?:canonical|alternate)"[^>]*>','',source)
        source=re.sub(r'<div class="language-switch".*?</div>',switch('/privacy/','/de/datenschutz/',lang),source,count=1)
        source=source.replace('<html lang="en">',f'<html lang="{lang}">')
        source=source.replace('</head>',f'<link rel="canonical" href="https://kaylummitsch.com{route}">'+alternates('/privacy/','/de/datenschutz/')+'</head>',1)
        if de:
            source=re.sub(r'<a class="skip".*?</header>',de_nav('/privacy/','/de/datenschutz/'),source,count=1,flags=re.S)
            source=source.replace('Skip to content','Zum Inhalt').replace('Find me on LinkedIn ↗','Auf LinkedIn verbinden ↗').replace('Made with curiosity. /kay','Mit Neugier gemacht. /kay')
        target=OUT/route.strip('/')/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(source)
    for page in OUT.rglob('*.html'):
        s=page.read_text();de='<html lang="de">' in s
        s=re.sub(r'<script>\s*\(function\(s,e,n,d,er\).*?</script>','',s,flags=re.S)
        s=re.sub(r'<!-- Cloudflare Web Analytics -->.*?<!-- End Cloudflare Web Analytics -->','',s,flags=re.S)
        s=re.sub(r'<section class="subscription".*?</section>',lambda m:newsletter(de),s,flags=re.S)
        label='Datenschutz &amp; Einstellungen' if de else 'Privacy &amp; settings'
        link='Datenschutz' if de else 'Privacy';route='/de/datenschutz/' if de else '/privacy/'
        if 'data-privacy-settings' not in s:s=s.replace('</footer>',f'<a href="{route}">{link}</a><button type="button" class="privacy-footer-button" data-privacy-settings>{label}</button></footer>')
        if '/privacy.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="/privacy.css"><script src="/privacy.js" defer></script></head>',1)
        if 'privacy-noscript' not in s:s=s.replace('</body>',('<noscript><p class="privacy-noscript">'+('Ohne JavaScript ist die Besuchsstatistik deaktiviert. Die Newsletter-Anmeldung ist über den Link bei Sender erreichbar.' if de else 'Without JavaScript, visitor analytics is disabled. Newsletter signup is available through the link to Sender.')+'</p></noscript></body>'),1)
        page.write_text(s)
